const raw = $json["output"];

// Elimina los delimitadores ```json y ```
const cleaned = raw.replace(/^```json\n?/, '').replace(/```$/, '').replace(/\u00A0/g, ' ').replace(/^\s+|\s+$/g, '').trim();

try {
  // Primer parseo: convierte string JSON escapado a string plano
  const unescaped = JSON.parse(cleaned);

  // Segundo parseo: convierte string plano a objeto JSON
  const parsed = typeof unescaped === 'string' ? JSON.parse(unescaped) : unescaped;

  return [{ json: parsed }];
} catch (error) {
  throw new Error("❌ Error al parsear JSON:\n" + error.message + "\n\n🔍 Contenido:\n" + cleaned);
}

