  let unescaped = JSON.parse(fixedJson);

  // Segundo parseo: convierte string plano a objeto JSON
  let parsed = typeof unescaped === 'string' ? JSON.parse(unescaped) : unescaped;

  return [{ json: parsed }];
} catch (error) {
  throw new Error("❌ Error al parsear JSON:\n" + error.message + "\n\n🔍 Contenido procesado:\n" + cleaned);
}

// Función para completar campos faltantes de forma recursiva
