=<p><b>📋 Información General</b></p>
<div style="font-size:14px; line-height:1.6;">
{{
  $('6. Preparar Datos2').item.json.general.informacionGeneral
    // Convertir títulos a negrita y separar en párrafos
    .replace(/Empresa:/g, '<p><b>Empresa:</b>')
    .replace(/Ciudad de operación:/g, '</p><p><b>Ciudad de operación:</b>')
    .replace(/Sector:/g, '</p><p><b>Sector:</b>')
    .replace(/Introducción del negocio:/g, '</p><p><b>Introducción del negocio:</b>')
    .replace(/Necesidades del cliente:/g, '</p><p><b>Necesidades del cliente:</b></p><ul>')
    .replace(/Soluciones brindadas:/g, '</ul><p><b>Soluciones brindadas:</b></p><ul>')
    // Dividir por saltos de línea, limpiar líneas vacías y eliminar "•"
    .split(/\n+/)
    .filter(line => line.trim() !== '')
    .map(line => {
      if (!/<p><b>/.test(line)) {
        return `<li>${line.replace(/•\s*/g, '').trim()}</li>`;
      }
      return line;
    })
    .join('')
    .concat('</ul>')
}}
</div>

=<p><b>📄 Resumen:</b></p>
<p>{{ $('fireflies2').item.json.data.transcript.summary.short_summary }}</p>

<hr>

<p><b>✅ Acuerdos:</b></p>
<ul style="margin:0; padding-left:20px;">
{{ $('fireflies2').item.json.data.transcript.summary.action_items
  .split('\n')
  .filter(line => line.trim() !== '')
  .map(line => {
    if (/\*\*(.*?)\*\*/.test(line)) {
      // Línea con **texto** -> se convierte en párrafo sin bullet y en negrita
      return `</ul><p style="margin:10px 0 4px 0;"><b>${line.replace(/\*\*/g, '')}</b></p><ul style="margin:0; padding-left:20px;">`;
    } else {
      // Línea normal -> bullet
      return `<li>${line}</li>`;
    }
  })
  .join('') }}
</ul>


<hr>

<p><b>🕒 Temas Tratados:</b></p>
<div style="font-size:14px; line-height:1.6;">
{{ $('fireflies2').item.json.data.transcript.summary.shorthand_bullet
  // Convierte **negritas** de Markdown a HTML
  .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')
  // Divide por saltos de línea dobles (párrafos)
  .split(/\n{2,}/)
  .filter(line => line.trim() !== '')
  .map(block => `<p style="margin:0 0 10px 0;">${block.replace(/\n/g, '<br>')}</p>`)
  .join('') }}
</div>

