// Obtener la cadena de participantes desde el nodo "fireflies"
const participantsString = $('fireflies2').first().json.data.transcript.participants[0] || "";

// 1. Dividir la cadena por comas y normalizar espacios
const mobilvendorEmails = participantsString
  .split(',')
  .map(email => email.trim())
  .filter(email => email.endsWith('@mobilvendor.com'));

// 2. Eliminar duplicados
const uniqueMobilvendorEmails = [...new Set(mobilvendorEmails)];

// 3. Devolver como array y como string
return [
  {
    json: {
      mobilvendor_emails: uniqueMobilvendorEmails, // como array
      mobilvendor_emails_string: uniqueMobilvendorEmails.join(',') // como string
    }
  }
];

// Obtenemos el campo summary del JSON
const summaryObj = $json?.data?.transcript?.summary ?? null;

let summaryText = "vacio";

if (summaryObj && typeof summaryObj === "object") {
  // Si existe short_summary y no está vacío
  if (summaryObj.short_summary && summaryObj.short_summary.trim() !== "") {
    summaryText = "lleno";
  }
}

return [
  {
    json: {
      summary: summaryText,
      originalData: $json
    }
  }
];

